 const auto h=read<uint16_t>(root,"full-chunk-state-bf16.bin",size_t(chunks)*524288);
 const auto g=read<float>(root,"full-g-cumsum-f32.bin",size_t(tokens)*32);
 const auto table=read<unsigned char>(root,"sm121-exp2-negative-f490940d.bin",qrt_sm121_exp2::table_bytes);
 require(qrt_sm121_exp2::valid_layout(table.data(),table.size()),"original table layout");
 std::vector<norm::Norm> wn(w.size()/128),hn(h.size()/128);
 std::vector<unsigned char> wok(wn.size()),hok(hn.size());
 for(size_t i=0;i<wn.size();++i){bool ok;wn[i]=summarize(w.data()+i*128,&ok);wok[i]=ok;}
 for(size_t i=0;i<hn.size();++i){bool ok;hn[i]=summarize(h.data()+i*128,&ok);hok[i]=ok;}
 std::atomic<unsigned> next{0u};std::array<std::thread,4> workers;std::array<Counts,4> counts{};
 for(unsigned worker=0;worker<4u;++worker)workers[worker]=std::thread([&,worker]{
  Counts& c=counts[worker];
  for(unsigned at=next.fetch_add(1u);at<chunks*32u;at=next.fetch_add(1u)){
   const unsigned chunk=at/32u,head=at%32u,first=chunk*64u,valid=std::min(64u,tokens-first),last=first+valid-1u;
   for(unsigned tile=0;tile<16u;++tile){
    const unsigned column=tile*8u+(chunk+head+tile)%8u;
    const size_t hi=size_t(at)*128u+column;
    uint16_t residual[64]{};
    for(unsigned row=0;row<valid;++row){
     const size_t wi=size_t(first+row)*32u+head,index=wi*128u+column;
     const float dot=original_dot(w.data()+wi*128u,h.data()+hi*128u);
     const float delta=consumer::subtract(bf16(u[index]),dot);
     require(rounded(delta)==v[index],"sampled original residual differs from GB10");
     volatile float difference=g[size_t(last)*32u+head]-g[size_t(first+row)*32u+head];
     volatile float argument=difference*1.4426950408889634074f;
     const float decay=qrt_sm121_exp2::evaluate(table.data(),argument);
     residual[row]=rounded(consumer::multiply(delta,decay));++c.wh;
     if(wok[wi]&&hok[hi]){
      float actual=123.25f;
      require(product::dot<128u>(w.data()+wi*128u,h.data()+hi*128u,&actual),"narrow WH unexpectedly declined");
      require(raw(actual)==raw(dot),"narrow WH carry differs from original integer");++c.wh_narrow;
     }else{
      uint16_t updated=0xa5a5u,scaled=0xa5a5u;
      if(consumer::residual(norm::enclose(wn[wi],hn[hi]),bf16(u[index]),decay,&updated,&scaled)){
       require(updated==v[index]&&scaled==residual[row],"certified sampled consumers differ");++c.wh_certified;
      }else{require(updated==0xa5a5u&&scaled==0xa5a5u,"declined certificate published");++c.wh_declined;}
     }
    }
    for(unsigned sample=0;sample<8u;++sample){
     const unsigned feature=(chunk*13u+head*7u+column*3u+sample*17u)%128u;
     uint16_t keys[64]{};bool narrow=true;
     for(unsigned row=0;row<valid;++row){keys[row]=k[(size_t(first+row)*16u+head/2u)*128u+feature];narrow=narrow&&eligible(keys[row],95u,159u)&&eligible(residual[row],95u,159u);}
     const float expected=original::dot_bf16_hopper(keys,residual,64u);
     float actual=123.25f;++c.kv;
     if(product::dot<64u>(keys,residual,&actual)){
      require(raw(actual)==raw(expected),"sampled KV carry differs from original integer");++c.kv_admitted;if(!narrow)++c.kv_extra;
     }else{require(actual==123.25f&&!narrow,"rejected KV published or declined original narrow domain");++c.kv_declined;}
    }
   }
  }
 });
 for(auto& worker:workers)worker.join();Counts c;
 for(const auto& x:counts){c.wh+=x.wh;c.wh_narrow+=x.wh_narrow;c.wh_certified+=x.wh_certified;c.wh_declined+=x.wh_declined;c.kv+=x.kv;c.kv_admitted+=x.kv_admitted;c.kv_extra+=x.kv_extra;c.kv_declined+=x.kv_declined;}
 require(c.wh==size_t(tokens)*32u*16u&&c.kv==size_t(chunks)*32u*16u*8u,"sample coverage");
 require(c.wh_certified&&c.wh_declined&&c.kv_extra&&c.kv_declined,"sample branches missing");
 std::printf("{\"kind\":\"original_gb10_hybrid_integer_samples\",\"tokens\":%u,\"workers\":4,\"wh_original_integer_dots\":%zu,\"wh_gb10_residuals_exact\":%zu,\"wh_narrow_carry_dots_exact\":%zu,\"wh_both_consumers_certified_exact\":%zu,\"wh_certificates_declined\":%zu,\"kv_original_integer_dots\":%zu,\"kv_product_carry_dots_exact\":%zu,\"kv_extra_over_operand_domain\":%zu,\"kv_declined_without_publishing\":%zu,\"raw_mismatches\":0,\"native_executed\":false,\"inference_acceptance\":false}\n",tokens,c.wh,c.wh,c.wh_narrow,c.wh_certified,c.wh_declined,c.kv,c.kv_admitted,c.kv_extra,c.kv_declined);
 return 0;
}catch(const std::exception& e){std::fprintf(stderr,"%s\n",e.what());return 1;}
